  private exp = new Map<string, number>();
  constructor(private ttl: number) {}

  issue(tokenId: string, now: number): void {
    this.exp.set(tokenId, now + this.ttl);
  }

  renew(tokenId: string, now: number): void {
    const e = this.exp.get(tokenId);
    if (e !== undefined && e > now) this.exp.set(tokenId, now + this.ttl);
  }

  countLive(now: number): number {
    let live = 0;
    for (const e of this.exp.values()) if (e > now) live++;
    return live;
  }
}

