class TokenKeeper {
  private exp = new Map<string, number>(); // ordered by expiry, earliest first
  constructor(private ttl: number) {}

  private prune(now: number): void {
    for (const [id, e] of this.exp) {
      if (e > now) break;
      this.exp.delete(id);
    }
  }

  issue(tokenId: string, now: number): void {
    this.prune(now);
    this.exp.set(tokenId, now + this.ttl);
  }

  renew(tokenId: string, now: number): void {
    this.prune(now);
    if (!this.exp.has(tokenId)) return;
    this.exp.delete(tokenId); // re-insert so it moves to the back
    this.exp.set(tokenId, now + this.ttl);
  }

  countLive(now: number): number {
    this.prune(now);
    return this.exp.size;
  }
}

