        while self.exp and next(iter(self.exp.values())) <= now:
            self.exp.popitem(last=False)

    def issue(self, tokenId: str, now: int) -> None:
        self._prune(now)
        self.exp[tokenId] = now + self.ttl

    def renew(self, tokenId: str, now: int) -> None:
        self._prune(now)
        if tokenId in self.exp:
            self.exp[tokenId] = now + self.ttl
            self.exp.move_to_end(tokenId)

    def countLive(self, now: int) -> int:
        self._prune(now)
        return len(self.exp)

